public static void check(Solution solution) {
    assert Arrays.equals(solution.numWays(new int[]{"a","b","c"}, "abc"), 0);
    assert Arrays.equals(solution.numWays(new int[]{"abc","def"}, "ad"), 0);
    assert Arrays.equals(solution.numWays(new int[]{"mississippi"}, "issi"), 15);
    assert Arrays.equals(solution.numWays(new int[]{"aaa","aaa","aaa"}, "aaa"), 27);
    assert Arrays.equals(solution.numWays(new int[]{"abc","acb","bac","bca","cab","cba"}, "abc"), 8);
    assert Arrays.equals(solution.numWays(new int[]{"abc","bcd","cde"}, "abc"), 1);
